import{_ as o,o as e,c as r,ah as l}from"./chunks/framework.DjU4PSOm.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"기능주의와 계산주의","slug":"기능주의와-계산주의","link":"#기능주의와-계산주의","children":[]},{"level":2,"title":"튜링 테스트","slug":"튜링-테스트","link":"#튜링-테스트","children":[]},{"level":2,"title":"구문론과 의미론","slug":"구문론과-의미론","link":"#구문론과-의미론","children":[]},{"level":2,"title":"중국어 방 사고실험","slug":"중국어-방-사고실험","link":"#중국어-방-사고실험","children":[]},{"level":2,"title":"반론과 재반박","slug":"반론과-재반박","link":"#반론과-재반박","children":[{"level":3,"title":"시스템 반론 (Systems Reply)","slug":"시스템-반론-systems-reply","link":"#시스템-반론-systems-reply","children":[]},{"level":3,"title":"로봇 반론 (Robot Reply)","slug":"로봇-반론-robot-reply","link":"#로봇-반론-robot-reply","children":[]}]}],"relativePath":"philosophy/Philosophy-of-Mind/06. 중국어 방 논증.md","filePath":"philosophy/Philosophy-of-Mind/06. 중국어 방 논증.md"}'),a={name:"philosophy/Philosophy-of-Mind/06. 중국어 방 논증.md"};function s(n,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[l('<h2 id="기능주의와-계산주의" tabindex="-1">기능주의와 계산주의 <a class="header-anchor" href="#기능주의와-계산주의" aria-label="Permalink to &quot;기능주의와 계산주의&quot;">​</a></h2><p>기능주의는 자연스럽게 <strong>계산주의(computationalism)</strong>로 이어진다 — 두뇌와 마음의 관계는 하드웨어와 소프트웨어의 관계와 같다는 입장이다. 조금 더 구체적으로는 (i) 인지 과정과 마음 상태는 본질적으로 정보처리이며, (ii) 정보처리는 구문론적 규칙에 따른 기호 계산으로 이해될 수 있다는 두 주장으로 이루어진다. 마음 상태를 기능적 상태로 본다면 디지털 컴퓨터로 그것을 실현하는 것도 원리적으로 가능해 보이므로, 계산주의는 기능주의에서 자연스럽게 따라 나온다.</p><p><strong>존 설(John Searle)</strong>의 <strong>중국어 방(Chinese Room) 논증</strong>은 이 계산주의와 기능주의에 중대한 물음을 던지는 것으로 널리 알려져 있다. 다만 설이 생각하는 것처럼 이것이 계산주의에 대한 결정적 반박이 되는지는 여전히 상당한 논란거리다. (참고 구분: <strong>강한 인공지능(Strong AI)</strong> — 적절히 프로그램된 컴퓨터는 문자 그대로 마음을 가진다는 입장 — vs. <strong>약한 인공지능(Weak AI)</strong> — 컴퓨터는 마음을 연구하는 유용한 도구일 뿐이라는 입장.)</p><h2 id="튜링-테스트" tabindex="-1">튜링 테스트 <a class="header-anchor" href="#튜링-테스트" aria-label="Permalink to &quot;튜링 테스트&quot;">​</a></h2><p>앨런 튜링은 기계가 마음을 가지는지 판별하는 테스트를 제안했다 — 기계와 대화해 보아 그것이 기계인지 사람인지 구별할 수 없다면 지능이 있는 것으로 판단한다는 것. (초기 챗봇 &quot;엘리자(ELIZA)&quot;의 대화 예시가 이런 시험의 소박한 사례로 종종 인용된다.)</p><p>튜링 테스트에는 두 방향의 반론이 있다.</p><ul><li><strong>지나치게 강하다</strong>: 튜링 테스트를 통과하지 못한다고 해서 초보적인 지능조차 없다고 볼 이유는 없어 보인다.</li><li><strong>지나치게 약하다</strong>: 행동주의를 전제하지 않는 한, 테스트를 통과한다고 해서 진정한 의미의 지능(이해)을 가진다고 볼 이유도 없어 보인다.</li></ul><h2 id="구문론과-의미론" tabindex="-1">구문론과 의미론 <a class="header-anchor" href="#구문론과-의미론" aria-label="Permalink to &quot;구문론과 의미론&quot;">​</a></h2><p>설의 핵심 아이디어는 컴퓨터 프로그램이 순전히 형식적·<strong>구문론적(syntactic)</strong>으로 규정될 수 있는 데 반해, 인간의 마음은 <strong>의미론적(semantic)</strong> 측면을 갖는다는 것이다.</p><ul><li><strong>구문론(syntax)</strong>: 기호의 형태·문법에만 관련된 측면.</li><li><strong>의미론(semantics)</strong>: 기호의 의미, 또는 기호가 세계와 맺는 관계.</li></ul><blockquote><p>&quot;마음에는 형식적 또는 구문론적 과정 이상의 것이 있다. … 나의 생각이 일련의 기호들로 나타난다 할지라도, 그 생각에는 추상적 기호 이상의 어떤 것이 있어야 한다. 그 추상적 기호들 자체로는 아무 의미도 가질 수 없기 때문이다. … 어떤 컴퓨터 프로그램도 마음이 될 수 없는 것은 단순히 다음과 같은 이유다. 컴퓨터 프로그램은 구문론적이지만, 마음은 구문론 이상의 것이다.&quot;</p></blockquote><h2 id="중국어-방-사고실험" tabindex="-1">중국어 방 사고실험 <a class="header-anchor" href="#중국어-방-사고실험" aria-label="Permalink to &quot;중국어 방 사고실험&quot;">​</a></h2><p>방 안에 있는 사람은 중국어를 전혀 이해하지 못한 채, 방으로 들어오는 중국어 &quot;질문&quot;에 대해 규칙책(기호의 <strong>모양</strong>에만 의존하는 순전히 구문론적 규칙)을 찾아 중국어 &quot;답변&quot;을 출력한다. 방 밖에서 보면 이 방(시스템)은 마치 중국어를 이해하고 대답하는 것처럼 보이지만, 방 안에서 기호를 조작하는 당사자는 명백히 중국어를 이해하지 못한다.</p><blockquote><p>&quot;당신은 형식적 컴퓨터 프로그램을 구현함으로써 마치 중국어를 이해하는 듯이 행동한다. 그럼에도 당신은 중국어 단어 하나조차 이해하지 못한다. 만일 중국어를 이해하는 적절한 프로그램을 몸소 수행하는 것만으로 당신이 중국어를 이해할 수 없다면, 어떤 다른 디지털 컴퓨터도 단순히 그 프로그램을 수행함으로써 중국어를 이해할 수 없을 것이다.&quot;</p></blockquote><p>논증으로 재구성하면:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>중국어 방 안에 있는 사람은 단순한 문자 조작만으로는 중국어를 이해할 수 없다</td></tr><tr><td>P2</td><td>그 사람이 문자 조작만으로 중국어를 이해할 수 없다면, 디지털 컴퓨터 역시 중국어를 이해할 수 없다</td></tr><tr><td>C</td><td>따라서 디지털 컴퓨터는 중국어를 이해할 수 없다</td></tr></tbody></table><p>설은 이 논증이 컴퓨터 기술의 특정 단계나 미래의 진보(직렬/병렬 처리, 처리 속도, 로봇 공학의 발전 등)와 전혀 무관하다고 강조한다 — 문제는 순전히 구문론적 기호 조작이 의미론적 이해를 낳을 수 있는가라는 원리적 물음이라는 것.</p><p><strong>시뮬레이션과 복제(duplication)의 구분</strong>도 이 논증의 배경에 있다 — 일반적으로 어떤 것을 시뮬레이션한다고 해서 그것의 모든 성질을 실제로 갖는다고 기대하지 않는다(화재 시뮬레이션이 집을 태우지는 않는다). 그렇다면 마음에 대한 (형식적) 시뮬레이션이 마음 자체를 갖는다고 여길 이유가 있는가?</p><h2 id="반론과-재반박" tabindex="-1">반론과 재반박 <a class="header-anchor" href="#반론과-재반박" aria-label="Permalink to &quot;반론과 재반박&quot;">​</a></h2><h3 id="시스템-반론-systems-reply" tabindex="-1">시스템 반론 (Systems Reply) <a class="header-anchor" href="#시스템-반론-systems-reply" aria-label="Permalink to &quot;시스템 반론 (Systems Reply)&quot;">​</a></h3><p>이해의 주체가 되어야 할 것은 방 안의 사람이 아니라 <strong>방 전체(시스템)</strong>이며, 방 안의 사람은 그 시스템의 중앙처리장치에 불과하다는 반론이다. 다음 논증 형식이 일반적으로 타당하지 않다는 점(부분과 전체를 혼동하는 <strong>결합의 오류</strong>)에 근거한다.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>P1</td><td>x는 y의 (중요한) 부분이다</td></tr><tr><td>P2</td><td>x는 F라는 성질을 갖지 않는다</td></tr><tr><td>C</td><td>따라서 y는 F라는 성질을 갖지 않는다</td></tr></tbody></table><p><strong>설의 재반박</strong>: &quot;시스템이 구문론에서 의미론으로 이행하는 방법은 없다. 중앙처리장치에 해당하는 나는 그 글자들이 무엇을 의미하는지 알 방도가 없으며, 그 전체 시스템도 마찬가지다.&quot; 설은 나아가 한 사람이 규칙책 전체를 통째로 암기해(&quot;내면화&quot;) 방 전체 역할을 혼자 수행하는 경우를 상상해 보자고 제안한다 — 이 경우에도 여전히 이해는 발생하지 않는다는 것이 설의 대답이다.</p><h3 id="로봇-반론-robot-reply" tabindex="-1">로봇 반론 (Robot Reply) <a class="header-anchor" href="#로봇-반론-robot-reply" aria-label="Permalink to &quot;로봇 반론 (Robot Reply)&quot;">​</a></h3><p>중국어를 이해하는 프로그램을 로봇 안에 넣고, 그 로봇이 카메라·팔다리 등을 통해 세계와 실제로 <strong>인과적으로 상호작용</strong>하게 한다면 어떨까? 핵심 아이디어는 기호 자체만으로는 의미론적 속성이 결정될 수 없지만, 기호가 대상들과의 상호작용을 통해 의미를 획득할 수 있다는 것이다.</p><p>설의 재반박: 로봇 두개골 속 방에서 기호를 조작하는 사람은, 카메라로 들어온 기호와 팔다리를 움직이는 출력 기호를 다루면서도 그 기호들이 무엇에 대응하는지, 어디서 왔는지 전혀 알지 못한다 — &quot;그 상호작용이 마음에 표상되지 않는 한, 로봇과 외부 세계의 인과적 상호작용은 무관할 뿐이다.&quot;</p><p>이 로봇 반론과 시스템 반론을 결합하면 더 강력한 반론이 될 수 있다는 지적도 있다. 계산주의자를 포함한 많은 철학자들은 마음의 <strong>지향성(intentionality)</strong> 또는 의미론적 성격이 세계와의 인과관계를 통해 설명될 수 있다고 주장한다.</p><p><strong>남는 물음</strong>: 설 자신도 유물론(생물학적 자연주의)을 지지하는 이상, 지향성/의미의 문제는 그에게도 난제로 남는다 — 마음이 결국 두뇌(물리적 과정)에 불과하다면, 그 의미는 대체 어디서 발생하는가? 유물론이 지향성을 설명할 수 있다면, 그 설명이 계산주의에도 똑같이 적용되지 못할 이유가 있는가 하는 질문이 남는다.</p>',28)])])}const c=o(a,[["render",s]]);export{g as __pageData,c as default};
